int Search(int[] a, int target) {
    int lo = 0, hi = a.Length - 1;          // кандидаты — a[lo..hi]
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;       // середина без переполнения
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;  // левая половина — мимо
        else hi = mid - 1;                  // правая половина — мимо
    }
    return -1;
}

