public int[] TwoSum(int[] nums, int target) {
    var seen = new Dictionary<int, int>();  // число → индекс
    for (int i = 0; i < nums.Length; i++) {
        // инвариант: в seen ровно nums[0..i-1]
        int need = target - nums[i];
        if (seen.TryGetValue(need, out int j)) return new[] { j, i };
        seen[nums[i]] = i;                  // сначала проверка, потом вставка
    }
    return new int[0];
}

