public bool ContainsNearbyDuplicate(int[] nums, int k) {
    var last = new Dictionary<int, int>();   // значение → последний индекс левее i
    for (int i = 0; i < nums.Length; i++) {
        if (last.TryGetValue(nums[i], out int j) && i - j <= k)
            return true;                     // то же число не дальше k
        last[nums[i]] = i;                   // инвариант: теперь последний — i
    }
    return false;
}

bool NearbyDuplicate(int[] nums, int k) {
